#include <Aevrynd/Renderer.h>
#include <cmath>
#include <iostream>
#include <limits>
#include <string>
using namespace Aevrynd;
int main(){
 BloomSettings3D settings{};if(!settings.enabled||BloomSoftThreshold3D(.5f,settings)!=0.f||BloomSoftThreshold3D(2.f,settings)<=0.f){std::cerr<<"Bloom threshold response failed\n";return 1;}
 settings.enabled=false;if(BloomSoftThreshold3D(8.f,settings)!=0.f){std::cerr<<"Disabled bloom must be zero cost\n";return 2;}
 settings={true,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-2.f,99.f,true,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity()};settings=NormalizeBloomSettings3D(settings);
 if(settings.threshold!=1.f||settings.softKnee!=.5f||settings.intensity!=0.f||settings.radiusPixels!=16.f||settings.depthThreshold!=.02f||settings.depthSoftness!=.02f){std::cerr<<"Bloom normalization failed\n";return 3;}
 DrawList draw;if(draw.ExposureCompensation()!=0.f){std::cerr<<"Zero EV default parity failed\n";return 4;}draw.SetExposureCompensation(std::numeric_limits<float>::infinity());if(draw.ExposureCompensation()!=0.f){std::cerr<<"Non-finite exposure did not fail closed\n";return 5;}draw.SetExposureCompensation(99.f);draw.SetBloom({true,1.2f,.4f,.2f,3.f});if(draw.ExposureCompensation()!=10.f||std::abs(draw.Bloom().intensity-.2f)>.0001f||!draw.Bloom().depthAware){std::cerr<<"Bloom API state failed\n";return 6;}
 BloomSettings3D depth{};if(BloomDepthSemanticWeight3D(.5f,1.f,0.f,depth)!=0.f||BloomDepthSemanticWeight3D(1.f,.5f,0.f,depth)!=0.f||BloomDepthSemanticWeight3D(.5f,.5f,0.f,depth)<.999f||BloomDepthSemanticWeight3D(.2f,.8f,0.f,depth)>.2f){std::cerr<<"Bloom depth semantic rejection failed\n";return 7;}depth.depthAware=false;if(BloomDepthSemanticWeight3D(.2f,.8f,0.f,depth)!=1.f||BloomDepthSemanticWeight3D(.2f,.8f,0.f,depth,false,true)!=1.f){std::cerr<<"Bloom depth fail-open failed\n";return 8;}
 const wchar_t* windowName=L"AevryndBloom3DSmoke";WNDCLASSW windowClass{};windowClass.lpfnWndProc=DefWindowProcW;windowClass.hInstance=GetModuleHandleW(nullptr);windowClass.lpszClassName=windowName;RegisterClassW(&windowClass);HWND window=CreateWindowW(windowName,windowName,WS_OVERLAPPED,0,0,96,64,nullptr,nullptr,windowClass.hInstance,nullptr);if(!window){std::cerr<<"Bloom runtime window failed\n";return 9;}
 D3D12Renderer renderer;renderer.Initialize(window,96,64,96,64,false);renderer.SetQualitySettings({false,false,false,false});DrawList runtimeDraw;runtimeDraw.SetViewProjection(Matrix4::Identity());runtimeDraw.WorldTriangle({-.6f,-.6f,.5f},{0,.6f,.5f},{.6f,-.6f,.5f},{4,.4f,.1f,1});runtimeDraw.SetBloom({true,.2f,.5f,.25f,2.f,true,.02f,.02f});renderer.Render(runtimeDraw,{.01f,.02f,.03f,1});renderer.WaitIdle();const RendererStats stats=renderer.GetStats();char expectedBuffer[16]{};const DWORD expectedLength=GetEnvironmentVariableA("AEVRYND_EXPECT_GPU_VALIDATION_MODE",expectedBuffer,DWORD(std::size(expectedBuffer)));const std::string expected=expectedLength&&expectedLength<std::size(expectedBuffer)?expectedBuffer:"normal";const bool clean=!stats.debugErrorCount&&!stats.debugWarningCount;const bool validation=expected=="gbv"?clean&&stats.gpuValidationRequested&&stats.gpuValidationAvailable&&stats.gpuValidationExecuted&&stats.gpuValidationPassed&&stats.debugLayerEnabled:expected=="normal"&&clean&&!stats.gpuValidationRequested&&!stats.gpuValidationAvailable&&!stats.gpuValidationExecuted&&!stats.gpuValidationPassed&&!stats.debugLayerEnabled;const bool runtime=stats.submittedFrames==1&&stats.bloomPasses==1&&stats.bloomDepthAwareEnabled&&stats.bloomSemanticReceipt.actual==BloomSemanticSource3D::HdrAlphaCarrier&&stats.bloomSemanticReceipt.available&&!stats.bloomSemanticReceipt.failOpen;DestroyWindow(window);if(!runtime||!validation){std::cerr<<"Bloom runtime smoke failed runtime="<<runtime<<" validation="<<validation<<" mode="<<expected<<" gbv="<<stats.gpuValidationRequested<<'/'<<stats.gpuValidationAvailable<<'/'<<stats.gpuValidationExecuted<<'/'<<stats.gpuValidationPassed<<'/'<<stats.debugLayerEnabled<<" debug="<<stats.debugErrorCount<<'/'<<stats.debugWarningCount<<'\n';return 9;}
 std::cout<<"Aevrynd bloom smoke passed mode="<<expected<<" source="<<uint32_t(stats.bloomSemanticReceipt.actual)<<" validation="<<validation<<" debug="<<stats.debugErrorCount<<'/'<<stats.debugWarningCount<<'\n';return 0;
}
